import {money,positive} from './domain.mjs';
const now=()=>new Date().toISOString();
const audit=(s,actor,action,extra)=>s.audit.push({at:now(),actor,action,...extra});
function actorName(actor){if(!actor?.trim())throw Error('Informe o responsável');return actor.trim()}
function costs(s,ids,fallback=new Map()){for(let id of ids){let m=s.materials.find(m=>m.id===id);if(!m)continue;let ps=s.proposals.filter(p=>p.materialId===id&&p.status==='approved'&&(!p.unit||p.unit===m.unit));ps.sort((a,b)=>String(a.decidedAt||s.audit.findLast(x=>x.proposalId===a.id&&x.action==='approved')?.at||a.at).localeCompare(String(b.decidedAt||s.audit.findLast(x=>x.proposalId===b.id&&x.action==='approved')?.at||b.at))||(s.audit.findLastIndex(x=>x.proposalId===a.id&&x.action==='approved')-s.audit.findLastIndex(x=>x.proposalId===b.id&&x.action==='approved')));let last=ps.at(-1);m.cost=last?last.cost:null;m.updated=last?(last.decidedAt||last.at):null}}
export function deleteRecord(state,kind,id,actor){actor=actorName(actor);let next=structuredClone(state),map={material:'materials',supplier:'suppliers',purchase:'purchases',quote:'quotes'},key=map[kind];if(!key)throw Error('Tipo inválido');let record=next[key].find(x=>x.id===id);if(!record)throw Error('Registro não encontrado');if(kind==='supplier'&&(next.materials.some(m=>m.supplier===id)||next.purchases.some(p=>p.supplierId===id)))throw Error('Fornecedor vinculado a materiais ou notas. Exclua os vínculos primeiro');if(kind==='material'&&(next.purchases.some(p=>p.items.some(x=>x.materialId===id))||next.quotes.some(q=>q.input?.lines.some(l=>l.materialId===id))))throw Error('Produto vinculado a nota ou orçamento. Exclua esses registros primeiro');let related={};if(kind==='purchase'){related.entries=next.entries.filter(e=>e.purchaseId===id);related.proposals=next.proposals.filter(p=>p.purchaseId===id);next.entries=next.entries.filter(e=>e.purchaseId!==id);next.proposals=next.proposals.filter(p=>p.purchaseId!==id);let approved=related.proposals.filter(p=>p.status==='approved');costs(next,new Set(approved.map(p=>p.materialId)),new Map(approved.map(p=>[p.materialId,p.old])))}if(kind==='material'){related.proposals=next.proposals.filter(p=>p.materialId===id);next.proposals=next.proposals.filter(p=>p.materialId!==id)}next[key]=next[key].filter(x=>x.id!==id);next.trash??=[];next.trash.push({id:crypto.randomUUID(),kind,record,related,deletedAt:now(),actor});audit(next,actor,'record-deleted',{kind,recordId:id,label:record.description||record.name||record.number,total:kind==='purchase'?record.total:undefined});Object.assign(state,next);return state}
export function restoreRecord(state,trashId,actor){actor=actorName(actor);let next=structuredClone(state),item=next.trash?.find(x=>x.id===trashId);if(!item)throw Error('Exclusão não encontrada');let {kind,record,related}=item,map={material:'materials',supplier:'suppliers',purchase:'purchases',quote:'quotes'},key=map[kind];if(next[key].some(x=>x.id===record.id))throw Error('Registro já existe');if(kind==='supplier'&&next.suppliers.some(s=>s.document===record.document))throw Error('Documento do fornecedor já cadastrado');if(kind==='material'){if(!next.suppliers.some(x=>x.id===record.supplier))throw Error('Restaure primeiro o fornecedor');if(next.materials.some(m=>m.code===record.code&&m.supplier===record.supplier))throw Error('Código de produto já cadastrado')}if(kind==='purchase'){if(record.key&&next.purchases.some(x=>x.key===record.key))throw Error('Nota já cadastrada');if(record.supplierId&&!next.suppliers.some(x=>x.id===record.supplierId))throw Error('Restaure primeiro o fornecedor');if(record.items.some(x=>x.materialId&&!next.materials.some(m=>m.id===x.materialId)))throw Error('Restaure primeiro os produtos da nota')}if(kind==='purchase'&&(related.proposals||[]).some(p=>p.unit&&next.materials.find(m=>m.id===p.materialId)?.unit!==p.unit))throw Error('A unidade dos produtos mudou. Confira os cadastros antes de restaurar a nota');if(kind==='quote'&&record.input.lines.some(x=>!next.materials.some(m=>m.id===x.materialId)))throw Error('Restaure primeiro os materiais do produto');next[key].push(record);if(related.entries)next.entries.push(...related.entries);if(related.proposals)next.proposals.push(...related.proposals);if(kind==='purchase')costs(next,new Set((related.proposals||[]).filter(p=>p.status==='approved').map(p=>p.materialId)));next.trash=next.trash.filter(x=>x.id!==trashId);audit(next,actor,'record-restored',{kind,recordId:record.id,label:record.description||record.name||record.number});Object.assign(state,next);return state}
export function lineValues({quantity,unitPrice,discount=0,freight=0,other=0}){let total=money(positive(quantity,'Quantidade',false)*positive(unitPrice,'Valor unitário')),purchaseTotal=money(total-positive(discount)+positive(freight)+positive(other));positive(purchaseTotal,'Total da compra');return {total,purchaseTotal}}
export function bindLineCalculations(doc){doc.addEventListener('input',event=>{let input=event.target,form=input?.closest?.('form');if(!form)return;let number=name=>Number(form.elements.namedItem(name)?.value||0);if(form.id==='purchase'){try{let v=lineValues({quantity:number('quantity'),unitPrice:number('unitPrice'),discount:number('discount'),freight:number('freight'),other:number('other')});form.elements.namedItem('total').value=v.total.toFixed(2);form.elements.namedItem('purchaseTotal').value=v.purchaseTotal.toFixed(2)}catch{form.elements.namedItem('total').value='';form.elements.namedItem('purchaseTotal').value=''}}let xmlMatch=input.name?.match(/^xml(Quantity|UnitPrice)(\d+)$/);if(form.id==='import'&&xmlMatch){let i=xmlMatch[2],quantity=number('xmlQuantity'+i),price=number('xmlUnitPrice'+i);form.elements.namedItem('xmlTotal'+i).value=quantity>0&&price>=0?money(quantity*price).toFixed(2):''}let match=input.name?.match(/^item(\d+)_(quantity|unitPrice)$/);if(form.id==='invoice-edit'&&match){let prefix='item'+match[1]+'_',quantity=number(prefix+'quantity'),price=number(prefix+'unitPrice'),total=form.elements.namedItem(prefix+'total');total.value=quantity>0&&price>=0?money(quantity*price).toFixed(2):''}})}
